lessons.solution_code:
def is_criticality_balanced(temperature, neutrons_emitted):
    """Return True when reactor is balanced."""
    return temperature < 800 and neutrons_emitted > 500


def reactor_efficiency(voltage, current, theoretical_max_power):
    """Return efficiency band as a colour string."""
    percentage_value = ((voltage * current) / theoretical_max_power) * 100
    if percentage_value >= 80:
        return "green"
    if percentage_value >= 60:
        return "orange"
    if percentage_value >= 30:
        return "red"
    return "black"


def fail_safe(temperature, neutrons_produced_per_second, threshold):
    """Return safety status string."""
    if temperature * neutrons_produced_per_second < 0.9 * threshold:
        return "LOW"
    if temperature * neutrons_produced_per_second <= 1.1 * threshold:
        return "NORMAL"
    return "DANGER"

